def countdown(n):
    if n <= 0:            # base case
        print("Blast off! 🚀")
        return
    print(n)
    countdown(n - 1)      # recursive step

countdown(3)

def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

print("5! =", factorial(5))

